package com.andye.warmod.radar.station.network;import com.andye.warmod.WarMod;import com.andye.warmod.radar.RadarTrackPhase;import com.andye.warmod.radar.station.*;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;public record ClientboundRadarStationObservationPayload(UUID radarId,List<RadarStationObservation>observations)implements CustomPacketPayload{public ClientboundRadarStationObservationPayload{observations=List.copyOf(observations.subList(0,Math.min(observations.size(),RadarStationConstants.MAX_OBSERVATIONS)));}public static final Type<ClientboundRadarStationObservationPayload>TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"radar_station_observations"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundRadarStationObservationPayload>STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUUID(p.radarId);b.writeVarInt(p.observations.size());for(var o:p.observations){b.writeUUID(o.trackId());b.writeVarInt(o.payloadType().ordinal());b.writeVarInt(o.phase().ordinal());writeVec3(b,o.observedPosition());writeVec3(b,o.observedVelocity());writeVec3(b,o.predictedImpactPosition());b.writeLong(o.observationGameTime());b.writeBoolean(o.threatensWarningZone());}},b->{UUID id=b.readUUID();int n=Math.min(RadarStationConstants.MAX_OBSERVATIONS,Math.max(0,b.readVarInt()));List<RadarStationObservation>list=new ArrayList<>();for(int i=0;i<n;i++)list.add(new RadarStationObservation(b.readUUID(),WarheadPayloadType.values()[Math.max(0,Math.min(WarheadPayloadType.values().length-1,b.readVarInt()))],RadarTrackPhase.values()[Math.max(0,Math.min(RadarTrackPhase.values().length-1,b.readVarInt()))],readVec3(b),readVec3(b),readVec3(b),b.readLong(),b.readBoolean()));return new ClientboundRadarStationObservationPayload(id,list);});private static void writeVec3(RegistryFriendlyByteBuf b,net.minecraft.world.phys.Vec3 v){b.writeDouble(v.x);b.writeDouble(v.y);b.writeDouble(v.z);}private static net.minecraft.world.phys.Vec3 readVec3(RegistryFriendlyByteBuf b){return new net.minecraft.world.phys.Vec3(b.readDouble(),b.readDouble(),b.readDouble());}@Override public Type<?extends CustomPacketPayload>type(){return TYPE;}}